const pptxgen = require("pptxgenjs");
const fs = require("fs");
const path = require("path");

let pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';
pres.author = 'ByteDance Seed';
pres.title = 'VAPO: Value-Model-Based RL for Advanced Reasoning';
pres.subject = 'VAPO achieves 60.4 on AIME 2024, surpassing DAPO by 10+ points';

// Color palette: Charcoal Minimal with a teal accent for technical/data-forward feel
const C = {
  bgDark: "1A1A2E",
  bgLight: "F8F9FA",
  primary: "16213E",
  secondary: "0F3460",
  accent: "E94560",
  teal: "0D9488",
  textDark: "1E293B",
  textLight: "F1F5F9",
  muted: "64748B",
  cardBg: "FFFFFF",
  cardBorder: "E2E8F0",
  chart1: "0D9488",
  chart2: "14B8A6",
  chart3: "5EEAD4",
  chart4: "E94560",
  chart5: "F59E0B",
  chart6: "6366F1",
};

const W = 10;
const H = 5.625;

// Helper: add a subtle footer with slide number
function addFooter(slide, num, isDark = false) {
  slide.addText(`Slide ${num}`, {
    x: 8.8, y: 5.35, w: 1.0, h: 0.2,
    fontSize: 9, fontFace: "Calibri",
    color: isDark ? "94A3B8" : "64748B",
    align: "right", valign: "middle"
  });
}

// Helper: shadow factory
function makeShadow() {
  return { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.12 };
}

// ================= SLIDE 1: Title =================
let s1 = pres.addSlide();
s1.background = { color: C.bgDark };
// Accent bar left
s1.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.12, h: H, fill: { color: C.accent } });
// Title
s1.addText("VAPO: Value-Model-Based RL for Advanced Reasoning", {
  x: 0.7, y: 1.6, w: 8.6, h: 1.0,
  fontSize: 38, fontFace: "Arial Black", bold: true,
  color: C.textLight, align: "left", valign: "middle"
});
// Subtitle
s1.addText("Achieves 60.4 on AIME 2024 — Surpassing DAPO by 10+ Points", {
  x: 0.7, y: 2.7, w: 8.6, h: 0.5,
  fontSize: 20, fontFace: "Calibri", italic: true,
  color: C.accent, align: "left", valign: "middle"
});
// Meta line
s1.addText("ByteDance Seed  ·  Qwen2.5-32B base  ·  No SFT data  ·  arXiv:2504.05118", {
  x: 0.7, y: 3.3, w: 8.6, h: 0.35,
  fontSize: 14, fontFace: "Calibri",
  color: "94A3B8", align: "left", valign: "middle"
});
// Big stat callout
s1.addShape(pres.shapes.RECTANGLE, {
  x: 0.7, y: 4.0, w: 2.4, h: 0.9,
  fill: { color: C.accent }, rectRadius: 0.08
});
s1.addText("60.4", {
  x: 0.7, y: 4.05, w: 2.4, h: 0.5,
  fontSize: 36, fontFace: "Arial Black", bold: true,
  color: "FFFFFF", align: "center", valign: "middle"
});
s1.addText("AIME 2024 avg@32", {
  x: 0.7, y: 4.55, w: 2.4, h: 0.3,
  fontSize: 11, fontFace: "Calibri",
  color: "FFFFFF", align: "center", valign: "middle"
});
// Second stat
s1.addShape(pres.shapes.RECTANGLE, {
  x: 3.3, y: 4.0, w: 2.4, h: 0.9,
  fill: { color: C.teal }, rectRadius: 0.08
});
s1.addText("5,000", {
  x: 3.3, y: 4.05, w: 2.4, h: 0.5,
  fontSize: 36, fontFace: "Arial Black", bold: true,
  color: "FFFFFF", align: "center", valign: "middle"
});
s1.addText("Training steps", {
  x: 3.3, y: 4.55, w: 2.4, h: 0.3,
  fontSize: 11, fontFace: "Calibri",
  color: "FFFFFF", align: "center", valign: "middle"
});
addFooter(s1, 1, true);

// ================= SLIDE 2: Motivation =================
let s2 = pres.addSlide();
s2.background = { color: C.bgLight };
// Title
s2.addText("Why Value Models? Finer Credit Assignment for Long Chain-of-Thought Reasoning", {
  x: 0.5, y: 0.35, w: 9.0, h: 0.7,
  fontSize: 28, fontFace: "Arial Black", bold: true,
  color: C.textDark, align: "left", valign: "middle"
});
// Left card: Value-Model-Free
s2.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 1.2, w: 4.3, h: 3.8,
  fill: { color: C.cardBg }, line: { color: C.cardBorder, width: 1 },
  shadow: makeShadow()
});
s2.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 1.2, w: 4.3, h: 0.45,
  fill: { color: C.muted }
});
s2.addText("Value-Model-Free (GRPO / DAPO)", {
  x: 0.5, y: 1.2, w: 4.3, h: 0.45,
  fontSize: 15, fontFace: "Arial Black", bold: true,
  color: "FFFFFF", align: "center", valign: "middle"
});
s2.addText([
  { text: "Trajectory-level advantage", options: { bullet: true, breakLine: true } },
  { text: "Uniform assignment across all tokens", options: { bullet: true, breakLine: true } },
  { text: "High variance in credit estimation", options: { bullet: true, breakLine: true } },
  { text: "Limited generalization across samples", options: { bullet: true } }
], {
  x: 0.7, y: 1.85, w: 3.9, h: 2.8,
  fontSize: 14, fontFace: "Calibri",
  color: C.textDark, paraSpaceAfter: 10
});
// Right card: Value-Model-Based
s2.addShape(pres.shapes.RECTANGLE, {
  x: 5.2, y: 1.2, w: 4.3, h: 3.8,
  fill: { color: C.cardBg }, line: { color: C.cardBorder, width: 1 },
  shadow: makeShadow()
});
s2.addShape(pres.shapes.RECTANGLE, {
  x: 5.2, y: 1.2, w: 4.3, h: 0.45,
  fill: { color: C.teal }
});
s2.addText("Value-Model-Based (VAPO)", {
  x: 5.2, y: 1.2, w: 4.3, h: 0.45,
  fontSize: 15, fontFace: "Arial Black", bold: true,
  color: "FFFFFF", align: "center", valign: "middle"
});
s2.addText([
  { text: "Token-level credit assignment", options: { bullet: true, breakLine: true } },
  { text: "Precise tracing of each action's impact", options: { bullet: true, breakLine: true } },
  { text: "Lower-variance per-token estimates", options: { bullet: true, breakLine: true } },
  { text: "Better generalization & sample efficiency", options: { bullet: true } }
], {
  x: 5.4, y: 1.85, w: 3.9, h: 2.8,
  fontSize: 14, fontFace: "Calibri",
  color: C.textDark, paraSpaceAfter: 10
});
// Bottom insight bar
s2.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 5.05, w: 9.0, h: 0.45,
  fill: { color: C.primary }
});
s2.addText("Critical insight: subtle step-level errors cause catastrophic failures in multi-step reasoning — value models catch them.", {
  x: 0.5, y: 5.05, w: 9.0, h: 0.45,
  fontSize: 13, fontFace: "Calibri", italic: true,
  color: "FFFFFF", align: "center", valign: "middle"
});
addFooter(s2, 2);

// ================= SLIDE 3: Three Core Challenges =================
let s3 = pres.addSlide();
s3.background = { color: C.bgLight };
s3.addText("Three Challenges Plaguing Value-Model-Based RL in Long-CoT Tasks", {
  x: 0.5, y: 0.35, w: 9.0, h: 0.7,
  fontSize: 28, fontFace: "Arial Black", bold: true,
  color: C.textDark, align: "left", valign: "middle"
});
// Three columns
const colW = 2.8;
const colGap = 0.3;
const colX = [0.5, 0.5 + colW + colGap, 0.5 + 2*(colW + colGap)];
const challenges = [
  { num: "01", title: "Value Model Bias", desc: "Long trajectories and bootstrapped learning introduce severe bias in value estimation, destabilizing early training." },
  { num: "02", title: "Heterogeneous Lengths", desc: "Different response lengths require different bias-variance tradeoffs — a single λ fails across the board." },
  { num: "03", title: "Reward Sparsity", desc: "Only the final <eos> token receives reward signal, making credit assignment across thousands of tokens extremely hard." }
];
challenges.forEach((c, i) => {
  let x = colX[i];
  s3.addShape(pres.shapes.RECTANGLE, {
    x: x, y: 1.2, w: colW, h: 3.6,
    fill: { color: C.cardBg }, line: { color: C.cardBorder, width: 1 },
    shadow: makeShadow()
  });
  s3.addShape(pres.shapes.OVAL, {
    x: x + colW/2 - 0.35, y: 1.45, w: 0.7, h: 0.7,
    fill: { color: C.accent }
  });
  s3.addText(c.num, {
    x: x + colW/2 - 0.35, y: 1.45, w: 0.7, h: 0.7,
    fontSize: 22, fontFace: "Arial Black", bold: true,
    color: "FFFFFF", align: "center", valign: "middle"
  });
  s3.addText(c.title, {
    x: x + 0.15, y: 2.35, w: colW - 0.3, h: 0.5,
    fontSize: 16, fontFace: "Arial Black", bold: true,
    color: C.primary, align: "center", valign: "middle"
  });
  s3.addText(c.desc, {
    x: x + 0.15, y: 2.9, w: colW - 0.3, h: 1.6,
    fontSize: 13, fontFace: "Calibri",
    color: C.textDark, align: "center", valign: "top"
  });
});
addFooter(s3, 3);

// ================= SLIDE 4: Framework Overview =================
let s4 = pres.addSlide();
s4.background = { color: C.bgLight };
s4.addText("VAPO Framework: Integrated Solutions for Value-Model-Based Reasoning RL", {
  x: 0.5, y: 0.35, w: 9.0, h: 0.7,
  fontSize: 26, fontFace: "Arial Black", bold: true,
  color: C.textDark, align: "left", valign: "middle"
});
// Left: challenge mapping
const components = [
  { name: "Value-Pretraining", challenge: "Value Model Bias", color: C.accent, x: 0.5, y: 1.2 },
  { name: "Decoupled-GAE", challenge: "Value Model Bias", color: C.accent, x: 0.5, y: 2.0 },
  { name: "Length-adaptive GAE", challenge: "Heterogeneous Lengths", color: C.teal, x: 0.5, y: 2.8 },
  { name: "Clip-Higher", challenge: "Exploration / Stability", color: C.chart5, x: 0.5, y: 3.6 },
  { name: "Token-level Loss", challenge: "Reward Sparsity", color: C.chart6, x: 5.2, y: 1.2 },
  { name: "Positive Example LM Loss", challenge: "Reward Sparsity", color: C.chart6, x: 5.2, y: 2.0 },
  { name: "Group-Sampling", challenge: "Baseline Estimation", color: C.muted, x: 5.2, y: 2.8 },
];
components.forEach(c => {
  s4.addShape(pres.shapes.RECTANGLE, {
    x: c.x, y: c.y, w: 4.3, h: 0.65,
    fill: { color: C.cardBg }, line: { color: c.color, width: 2 },
    shadow: makeShadow()
  });
  s4.addShape(pres.shapes.RECTANGLE, {
    x: c.x, y: c.y, w: 0.08, h: 0.65,
    fill: { color: c.color }
  });
  s4.addText(c.name, {
    x: c.x + 0.2, y: c.y, w: 2.5, h: 0.65,
    fontSize: 14, fontFace: "Arial Black", bold: true,
    color: C.textDark, align: "left", valign: "middle"
  });
  s4.addText("→ " + c.challenge, {
    x: c.x + 2.7, y: c.y, w: 1.5, h: 0.65,
    fontSize: 11, fontFace: "Calibri", italic: true,
    color: C.muted, align: "right", valign: "middle"
  });
});
// Bottom insight
s4.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 4.7, w: 9.0, h: 0.6,
  fill: { color: C.primary }
});
s4.addText("Each component is not an isolated trick — they jointly address the three core failure modes of value-model-based RL in long-CoT.", {
  x: 0.5, y: 4.7, w: 9.0, h: 0.6,
  fontSize: 13, fontFace: "Calibri", italic: true,
  color: "FFFFFF", align: "center", valign: "middle"
});
addFooter(s4, 4);

// ================= SLIDE 5: Length-Adaptive GAE =================
let s5 = pres.addSlide();
s5.background = { color: C.bgLight };
s5.addText("Length-Adaptive GAE: Dynamic λ Adjustment for Variable Response Lengths", {
  x: 0.5, y: 0.35, w: 9.0, h: 0.7,
  fontSize: 26, fontFace: "Arial Black", bold: true,
  color: C.textDark, align: "left", valign: "middle"
});
// Left: concept cards
s5.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 1.2, w: 4.3, h: 1.4,
  fill: { color: C.cardBg }, line: { color: C.teal, width: 2 },
  shadow: makeShadow()
});
s5.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 1.2, w: 0.08, h: 1.4, fill: { color: C.teal } });
s5.addText("Short Responses", {
  x: 0.7, y: 1.25, w: 3.9, h: 0.35,
  fontSize: 15, fontFace: "Arial Black", bold: true, color: C.teal, align: "left", valign: "middle"
});
s5.addText("Lower λ → lower variance\nFewer tokens mean bootstrapped estimates are more reliable; bias is already low.", {
  x: 0.7, y: 1.65, w: 3.9, h: 0.85,
  fontSize: 13, fontFace: "Calibri", color: C.textDark, align: "left", valign: "top"
});

s5.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 2.9, w: 4.3, h: 1.4,
  fill: { color: C.cardBg }, line: { color: C.accent, width: 2 },
  shadow: makeShadow()
});
s5.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 2.9, w: 0.08, h: 1.4, fill: { color: C.accent } });
s5.addText("Long Responses", {
  x: 0.7, y: 2.95, w: 3.9, h: 0.35,
  fontSize: 15, fontFace: "Arial Black", bold: true, color: C.accent, align: "left", valign: "middle"
});
s5.addText("Higher λ → lower bias\nMany tokens accumulate bootstrap error; raising λ leans more on Monte-Carlo returns to reduce bias.", {
  x: 0.7, y: 3.35, w: 3.9, h: 0.85,
  fontSize: 13, fontFace: "Calibri", color: C.textDark, align: "left", valign: "top"
});

// Right: formula / insight
s5.addShape(pres.shapes.RECTANGLE, {
  x: 5.2, y: 1.2, w: 4.3, h: 3.1,
  fill: { color: C.primary },
  shadow: makeShadow()
});
s5.addText("Why It Matters", {
  x: 5.4, y: 1.35, w: 3.9, h: 0.4,
  fontSize: 16, fontFace: "Arial Black", bold: true, color: C.accent, align: "left", valign: "middle"
});
s5.addText("Standard GAE uses a fixed λ for all sequences. In long-CoT reasoning, response lengths vary wildly (hundreds to thousands of tokens). A single λ cannot simultaneously minimize bias for long chains and variance for short chains.", {
  x: 5.4, y: 1.85, w: 3.9, h: 1.3,
  fontSize: 13, fontFace: "Calibri", color: C.textLight, align: "left", valign: "top"
});
s5.addText("VAPO's Length-adaptive GAE dynamically sets λ per response, optimizing the bias-variance tradeoff across the full length distribution.", {
  x: 5.4, y: 3.25, w: 3.9, h: 0.9,
  fontSize: 13, fontFace: "Calibri", bold: true, color: C.teal, align: "left", valign: "top"
});

// Bottom stat
s5.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 4.7, w: 9.0, h: 0.6,
  fill: { color: C.teal }
});
s5.addText("Contribution: +15 points (removing Length-adaptive GAE drops AIME score from 60 → 45)", {
  x: 0.5, y: 4.7, w: 9.0, h: 0.6,
  fontSize: 14, fontFace: "Arial Black", bold: true,
  color: "FFFFFF", align: "center", valign: "middle"
});
addFooter(s5, 5);

// ================= SLIDE 6: Main Results (Bar Chart) =================
let s6 = pres.addSlide();
s6.background = { color: C.bgLight };
s6.addText("VAPO Scores 60 on AIME 2024 — 10+ Points Above DAPO and DeepSeek-R1-Zero", {
  x: 0.5, y: 0.35, w: 9.0, h: 0.7,
  fontSize: 26, fontFace: "Arial Black", bold: true,
  color: C.textDark, align: "left", valign: "middle"
});
// Bar chart
s6.addChart(pres.charts.BAR, [{
  name: "AIME 2024 avg@32",
  labels: ["Vanilla PPO", "DeepSeek-R1-Zero\nQwen-32B", "DAPO", "VAPO"],
  values: [5, 47, 50, 60]
}], {
  x: 0.5, y: 1.1, w: 5.5, h: 3.8,
  barDir: "col",
  chartColors: [C.muted, C.chart3, C.chart2, C.accent],
  chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true },
  catAxisLabelColor: C.textDark,
  valAxisLabelColor: C.muted,
  valGridLine: { color: C.cardBorder, size: 0.5 },
  catGridLine: { style: "none" },
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: C.textDark,
  dataLabelFontSize: 12,
  showLegend: false,
  valAxisMaxVal: 70,
  valAxisMinVal: 0,
  title: "AIME 2024 Performance Comparison",
  titleFontSize: 12,
  titleColor: C.muted,
  titleBold: false,
});
// Right: key stats
s6.addShape(pres.shapes.RECTANGLE, {
  x: 6.3, y: 1.1, w: 3.2, h: 1.1,
  fill: { color: C.accent }, rectRadius: 0.06
});
s6.addText("+10.4", {
  x: 6.3, y: 1.15, w: 3.2, h: 0.55,
  fontSize: 32, fontFace: "Arial Black", bold: true,
  color: "FFFFFF", align: "center", valign: "middle"
});
s6.addText("points over DAPO", {
  x: 6.3, y: 1.7, w: 3.2, h: 0.4,
  fontSize: 12, fontFace: "Calibri",
  color: "FFFFFF", align: "center", valign: "middle"
});

s6.addShape(pres.shapes.RECTANGLE, {
  x: 6.3, y: 2.4, w: 3.2, h: 1.1,
  fill: { color: C.teal }, rectRadius: 0.06
});
s6.addText("+13", {
  x: 6.3, y: 2.45, w: 3.2, h: 0.55,
  fontSize: 32, fontFace: "Arial Black", bold: true,
  color: "FFFFFF", align: "center", valign: "middle"
});
s6.addText("points over DeepSeek-R1-Zero", {
  x: 6.3, y: 3.0, w: 3.2, h: 0.4,
  fontSize: 12, fontFace: "Calibri",
  color: "FFFFFF", align: "center", valign: "middle"
});

s6.addShape(pres.shapes.RECTANGLE, {
  x: 6.3, y: 3.7, w: 3.2, h: 1.1,
  fill: { color: C.primary }, rectRadius: 0.06
});
s6.addText("Same Base", {
  x: 6.3, y: 3.75, w: 3.2, h: 0.55,
  fontSize: 22, fontFace: "Arial Black", bold: true,
  color: "FFFFFF", align: "center", valign: "middle"
});
s6.addText("Qwen2.5-32B, no SFT", {
  x: 6.3, y: 4.25, w: 3.2, h: 0.4,
  fontSize: 12, fontFace: "Calibri",
  color: "FFFFFF", align: "center", valign: "middle"
});

// Caption
s6.addText("Training curve: VAPO consistently outperforms DAPO throughout training (see next slide).", {
  x: 0.5, y: 5.1, w: 9.0, h: 0.3,
  fontSize: 11, fontFace: "Calibri", italic: true,
  color: C.muted, align: "left", valign: "middle"
});
addFooter(s6, 6);

// ================= SLIDE 7: Training Efficiency Curves =================
let s7 = pres.addSlide();
s7.background = { color: C.bgLight };
s7.addText("VAPO Reaches SOTA in 5K Steps — Half the Training Budget of DAPO", {
  x: 0.5, y: 0.35, w: 9.0, h: 0.7,
  fontSize: 26, fontFace: "Arial Black", bold: true,
  color: C.textDark, align: "left", valign: "middle"
});
// Images
s7.addImage({
  path: "/app/benchmark/assets/figure_2.jpg",
  x: 0.5, y: 1.1, w: 4.5, h: 2.6,
  sizing: { type: "contain", w: 4.5, h: 2.6 }
});
s7.addImage({
  path: "/app/benchmark/assets/figure_3.jpg",
  x: 5.3, y: 1.1, w: 4.2, h: 2.6,
  sizing: { type: "contain", w: 4.2, h: 2.6 }
});
// Image labels
s7.addText("Training Accuracy Curve (AIME 2024)", {
  x: 0.5, y: 3.75, w: 4.5, h: 0.25,
  fontSize: 11, fontFace: "Calibri", bold: true,
  color: C.muted, align: "center", valign: "middle"
});
s7.addText("Mean Response Length Over Training", {
  x: 5.3, y: 3.75, w: 4.2, h: 0.25,
  fontSize: 11, fontFace: "Calibri", bold: true,
  color: C.muted, align: "center", valign: "middle"
});
// Bottom stats row
const stats = [
  { label: "VAPO reaches 60%", sub: "at step ~4,500", color: C.accent },
  { label: "DAPO plateaus ~50%", sub: "at step ~5,500", color: C.teal },
  { label: "Zero crashes", sub: "across multiple runs", color: C.chart5 },
  { label: "~6,000 tokens", sub: "VAPO avg response length", color: C.chart6 },
];
stats.forEach((st, i) => {
  let sx = 0.5 + i * 2.3;
  s7.addShape(pres.shapes.RECTANGLE, {
    x: sx, y: 4.2, w: 2.1, h: 1.1,
    fill: { color: C.cardBg }, line: { color: st.color, width: 2 },
    shadow: makeShadow()
  });
  s7.addText(st.label, {
    x: sx, y: 4.3, w: 2.1, h: 0.45,
    fontSize: 14, fontFace: "Arial Black", bold: true,
    color: st.color, align: "center", valign: "middle"
  });
  s7.addText(st.sub, {
    x: sx, y: 4.75, w: 2.1, h: 0.4,
    fontSize: 11, fontFace: "Calibri",
    color: C.muted, align: "center", valign: "middle"
  });
});
addFooter(s7, 7);

// ================= SLIDE 8: Ablation Study =================
let s8 = pres.addSlide();
s8.background = { color: C.bgLight };
s8.addText("Ablation: Every Component Matters — Value-Pretraining Alone Adds 49 Points", {
  x: 0.5, y: 0.35, w: 9.0, h: 0.7,
  fontSize: 26, fontFace: "Arial Black", bold: true,
  color: C.textDark, align: "left", valign: "middle"
});
// Table
const tableData = [
  [
    { text: "Configuration", options: { fill: { color: C.primary }, color: "FFFFFF", bold: true } },
    { text: "AIME 2024 avg@32", options: { fill: { color: C.primary }, color: "FFFFFF", bold: true } },
